#!/usr/bin/env node
/**
 * OmniContext content-script bundler (zero-dependency).
 * The extension manifest loads `src/content/content.bundle.js` as the content
 * script, but the source of truth lives in ES modules under src/. This script
 * statically resolves the import graph from src/content/content.js and
 * concatenates the modules into a single IIFE. It is intentionally simple:
 * the module graph uses only relative './' and '../' imports with no
 * re-exports or dynamic imports, so static resolution is sufficient.
 *
 * Usage:
 *   node scripts/bundle-content.js   (writes src/content/content.bundle.js)
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, normalize, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const ENTRY = join(ROOT, 'src/content/content.js');
const OUT = join(ROOT, 'src/content/content.bundle.js');

const IMPORT_RE = /^\s*import\s+([^'"\s]+(?:\s*,\s*[^'"\s]+)?|\{[^}]*\}|\*\s+as\s+[^'"\s]+)\s+from\s+['"]([^'"]+)['"]\s*;?\s*$/gm;

function resolveImport(fromFile, spec) {
  if (!spec.startsWith('.')) {
    throw new Error(`[bundle] Non-relative import "${spec}" in ${fromFile} — expected './' or '../'.`);
  }
  const base = dirname(fromFile);
  const resolved = normalize(join(base, spec));
  const candidates = [resolved, `${resolved}.js`];
  for (const c of candidates) {
    if (existsSync(c)) return c;
  }
  throw new Error(`[bundle] Cannot resolve "${spec}" from ${fromFile}`);
}

function collectGraph(entry) {
  const graph = new Map();
  const seen = new Set();

  function visit(file) {
    if (seen.has(file)) return;
    seen.add(file);
    const code = readFileSync(file, 'utf8');
    const imports = [];
    for (const match of code.matchAll(IMPORT_RE)) {
      imports.push(match[2]);
    }
    graph.set(file, { code, imports });
    for (const spec of imports) {
      visit(resolveImport(file, spec));
    }
  }

  visit(entry);
  return graph;
}

// Topological order: dependencies before dependents.
function orderGraph(graph, entry) {
  const ordered = [];
  const visited = new Set();

  function visit(file) {
    if (visited.has(file)) return;
    visited.add(file);
    const node = graph.get(file);
    for (const spec of node.imports) {
      visit(resolveImport(file, spec));
    }
    ordered.push(file);
  }

  visit(entry);
  return ordered;
}

function stripImports(code) {
  return code
    .replace(IMPORT_RE, '')
    .replace(/^\s*\/\*\*[\s\S]*?\*\/\s*/m, '')
    .replace(/^export\s+/gm, '')
    .trim();
}

const graph = collectGraph(ENTRY);
const order = orderGraph(graph, ENTRY);
const parts = [];

const banner = `/**
 * OmniContext bundled content script (GENERATED by scripts/bundle-content.js).
 * Do not edit directly — edit the ES modules under src/ and re-run
 *   npm run bundle:content
 */
(function () {
  'use strict';
`;

for (const file of order) {
  const rel = relative(ROOT, file);
  parts.push(`// ==== ${rel} ====`);
  parts.push(stripImports(graph.get(file).code));
}

const footer = `
})();`;

writeFileSync(OUT, banner + '\n\n' + parts.join('\n\n\n') + '\n\n' + footer + '\n');

const sizes = order.map((f) => `  ${relative(ROOT, f)}`).join('\n');
console.log(`[bundle] Wrote ${OUT}`);
console.log(`[bundle] Modules (${order.length}):\n${sizes}`);
